// The mirror layer's only source: resume.json, generated by CI from the one-pager.
// It is validated against its schema when the site builds, and a mismatch fails the build.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import Ajv2020 from "ajv/dist/2020.js";
import schema from "./resume.schema.json";

export interface Resume {
  basics: { name: string; citizenship: string; email: string; phone: string; links: { label: string; url: string }[] };
  education: { school: string; degree: string; honorific?: string; date: string; gpa: string; items: string[] }[];
  experience: { company: string; title: string; team?: string; dates: string; location: string; stack: string[]; bullets: string[] }[];
  projects: { slug: string; title: string; url: string; role?: string; dates: string; stack: string[]; bullets: string[] }[];
  skills: { languages: string[]; frameworks: string[]; tools: string[] };
  meta: { source: string; generatedAt: string; commit?: string };
}

const path = resolve(process.env.RESUME_JSON ?? "src/data/resume.json");
const data = JSON.parse(readFileSync(path, "utf8"));
const validate = new Ajv2020({ allErrors: true }).compile(schema);
if (!validate(data)) {
  const errors = validate.errors!.map((e) => `  ${e.instancePath || "/"} ${e.message}`).join("\n");
  throw new Error(`resume.json does not match its schema (${path}):\n${errors}`);
}

export const resume = data as Resume;

// Which profile a link is, by its host: "GitHub", "LinkedIn", or undefined for anything else.
const PROFILES: Record<string, string> = { "github.com": "GitHub", "linkedin.com": "LinkedIn" };
export const profileOf = (url: string): string | undefined => PROFILES[new URL(url).hostname.replace(/^www\./, "")];
export const profileLink = (name: string) => resume.basics.links.find((l) => profileOf(l.url) === name);
